package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.ConcurrentMap;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class LocaleUtils_countriesByLanguage_TriageGen0Test {

    @Test
    public void testCountriesByLanguage_NullLanguageCode() {
        List<Locale> result = LocaleUtils.countriesByLanguage(null);
        assertNotNull(result);
        assertTrue(result.isEmpty());
    }

    @Test
    public void testCountriesByLanguage_ExistingLanguageCode() {
        // Test with a language that is known to exist in standard JVM locales (e.g., "en")
        // This tests the branch where countries is NOT null (cached) or the logic for finding them.
        List<Locale> result = LocaleUtils.countriesByLanguage("en");
        assertNotNull(result);

        // Verify that all returned locales actually have "en" as the language
        for (Locale locale : result) {
            assertEquals("en", locale.getLanguage());
            assertFalse("Country should not be empty", locale.getCountry().isEmpty());
            assertTrue("Variant should be empty", locale.getVariant().isEmpty());
        }
    }

    @Test
    public void testCountriesByLanguage_NonExistentLanguageCode() {
        // Test with a language code that is highly unlikely to exist
        String nonExistentLang = "zzx";
        List<Locale> result = LocaleUtils.countriesByLanguage(nonExistentLang);

        assertNotNull(result);
        assertTrue("Result should be an empty list for non-existent language", result.isEmpty());
    }

    @Test
    public void testCountriesByLanguage_EmptyLanguageCode() {
        // Test with an empty string
        List<Locale> result = LocaleUtils.countriesByLanguage("");
        assertNotNull(result);
        assertTrue(result.isEmpty());
    }

    @Test
    public void testCountriesByLanguage_CachingMechanism() {
        // This test ensures the logic flows through the cache hit and cache miss paths
        String lang = "fr";

        // First call: populate cache
        List<Locale> firstCall = LocaleUtils.countriesByLanguage(lang);

        // Second call: should retrieve from cache
        List<Locale> secondCall = LocaleUtils.countriesByLanguage(lang);

        assertNotNull(firstCall);
        assertNotNull(secondCall);
        assertEquals("Cache should return the same list instance or equal content", firstCall, secondCall);

        // Verify unmodifiable property (as per code: Collections.unmodifiableList)
        if (!firstCall.isEmpty()) {
            try {
                firstCall.add(new Locale("fr", "FR"));
                fail("Expected UnsupportedOperationException because the list is unmodifiable");
            } catch (UnsupportedOperationException e) {
                // Success
            }
        }
    }
}
